 const[lang,setLang]=useState(()=>localStorage.getItem('gmxLanguage')||'English');
 useEffect(()=>{
  try{localStorage.setItem('gmxLanguage',lang);}catch{}
  const root=document.documentElement;
  root.lang=lang==='हिन्दी'?'hi':lang==='العربية'?'ar':lang==='Español'?'es':lang==='Français'?'fr':lang==='Deutsch'?'de':lang==='Italiano'?'it':lang==='Português'?'pt':lang==='Srpski'?'sr':'en';
  root.dir=lang==='العربية'?'rtl':'ltr';
  const applyTranslations=()=>{
   const dict=UI_TRANSLATIONS[lang]||{};
   const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
   let node;
   while((node=walker.nextNode())){
    if(!node.__gmxOriginalText)node.__gmxOriginalText=node.nodeValue;
    const original=node.__gmxOriginalText;
    const nextText=translateUiText(original,lang);
    if(node.nodeValue!==nextText)node.nodeValue=nextText;
   }
   document.querySelectorAll('input[placeholder],textarea[placeholder],button[aria-label],img[alt]').forEach(el=>{
    ['placeholder','aria-label','alt'].forEach(attr=>{
     if(!el.hasAttribute(attr))return;
     const key='__gmxOriginal_'+attr;
     if(!el[key])el[key]=el.getAttribute(attr);
     const nextValue=translateUiText(el[key],lang);
     if(el.getAttribute(attr)!==nextValue)el.setAttribute(attr,nextValue);
    });
   });
  };
  applyTranslations();
  const observer=new MutationObserver(()=>applyTranslations());
  observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','alt']});
  return()=>observer.disconnect();
 },[lang]);

